INSERT OR REPLACE INTO person VALUES ('4723073','Alfred Lin','アルフレッド・リン','American businessman','Alfred Lin (Chinese: 林君叡; born 1972) is a Taiwanese-American venture capitalist who has served as the managing partner of Sequoia Capital since 2025. He joined Sequoia in 2010 as partner, later taking over global investment operations alongside Pat Grady. Lin was the COO, CFO, and chairman of online retailer Zappos from 2005 to 2010.','en','Alfred Lin');
