INSERT OR REPLACE INTO person VALUES ('7357593','Roelof Botha','','South African businessman','Roelof Frederik Botha (born 19 September 1973) is a South African-American venture capitalist. He was at Sequoia Capital from 2003 to 2026, running its U.S. business from 2017 and leading the whole firm from 2022 to 2025. Before Sequoia he worked at PayPal from 2000 to 2003, and was its chief financial officer (CFO) when it went public in 2002.','en','Roelof Botha');
