INSERT OR REPLACE INTO person VALUES ('6289985','Joshua Kushner','ジョシュア・クシュナー','アメリカ合衆国の実業家 (1985-)','Joshua Kushner (born June 12, 1985) is an American businessman and venture capitalist. He is a founder and managing partner of the venture capital firm Thrive Capital, and co-founder and vice-chairman of Oscar Health. He is the youngest son of Charles Kushner, and the brother of Jared Kushner. Kushner also co-founded social games developer Vostu. In August 2026, Kushner bought the Los Angeles Lakers along with Bob Iger for a record $12.5 billion.','en','Joshua Kushner');
