INSERT OR REPLACE INTO person VALUES ('6384918','Keith Rabois','','American businessman','Keith Rabois (born March 17, 1969) is an American technology executive and investor. He is a managing director at Khosla Ventures and a co-founder of Opendoor. He was an early-stage startup investor, and executive, at PayPal, LinkedIn, and Square. Rabois invested in Yelp and the Xoom Corporation prior to each company''s initial public offering (IPO). For both investments he insisted on being a board of directors member. Rabois is considered a member of the PayPal Mafia.','en','Keith Rabois');
